#include <bits/stdc++.h>
#include <cstring>
using namespace std;
typedef long long ll;
const int N=200010;
ll n;
ll h[N],ne[N*2],e[N*2],idx;
ll dp[N],sum[N],tiao[N],tt[N],ans;
void add(int a,int b)
{
    e[idx]=b;
    ne[idx]=h[a];
    h[a]=idx++;
}
void dfs_zong(int u,int fa)//计算无加边情况下的距离总和
{
    sum[u]=1;
    tiao[u]=1;
    for(int i=h[u];i!=-1;i=ne[i])
    {
        int j=e[i];
        if(j==fa)continue;
        dfs_zong(j,u);
        sum[u]+=sum[j];
        dp[u]+=dp[j]+(n-sum[j])*sum[j]*2;
        if(u!=1)
        {
            tiao[fa]+=tiao[j];//动态计算跳跃节点数
        }
        tt[u]+=tiao[j];//此为计算该节点下直接相连的子节点跳跃节点数总和
    }
}
void dfs_jian(int u,int fa)
{
    for(int i=h[u];i!=-1;i=ne[i])
    {
        int j=e[i];
        if(j==fa)continue;
        dfs_jian(j,u);
        ans-=tiao[j]*(tt[u]-tiao[j]);//此为计算此节点下横边的贡献
        if(u!=1)
        {ans-=tiao[j]*(n-sum[u])*2;}//计算以此节点为中间节点的竖边的贡献，两倍是因为来回都算
    }
}
int main()
{
    cin>>n;
    memset(h,-1,sizeof(h));
    for(int i=0;i<n-1;i++)
    {
        int a,b;
        cin>>a>>b;
        add(a,b);
        add(b,a);
    }
    dfs_zong(1,-1);
    ans=dp[1];
    dfs_jian(1,-1);
    cout<<ans<<endl;
}
```

