import sys
sys.setrecursionlimit(300000)

def solve():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    dp = [0] * (n + 1)      # dp[u] 表示 u 子树内原始距离和（贡献形式）
    size = [0] * (n + 1)    # 子树大小
    tiao = [0] * (n + 1)    # 跳跃节点数
    tt = [0] * (n + 1)      # 直接子节点的跳跃节点数之和

    def dfs1(u, fa):
        size[u] = 1
        tiao[u] = 1
        for v in adj[u]:
            if v == fa:
                continue
            dfs1(v, u)
            size[u] += size[v]
            dp[u] += dp[v] + (n - size[v]) * size[v] * 2
            if u != 1:
                tiao[fa] += tiao[v]   # 将子节点跳跃信息向上传递
            tt[u] += tiao[v]

    def dfs2(u, fa):
        nonlocal ans
        for v in adj[u]:
            if v == fa:
                continue
            dfs2(v, u)
            # 横向新航道贡献
            ans -= tiao[v] * (tt[u] - tiao[v])
            if u != 1:
                # 纵向新航道贡献（双向乘2）
                ans -= tiao[v] * (n - size[u]) * 2

    dfs1(1, 0)
    ans = dp[1]
    dfs2(1, 0)
    print(ans)

if __name__ == "__main__":
    solve()
```

